script=f'''
const NEW_PROJECTS={repr([{'id':p[0],'title':p[1],'category':p[2],'tagline':p[3],'desc':p[4],'stack':p[5],'accent':p[6],'secondary':p[7],'glow':p[8],'surface':p[9],'label':p[10],'stat':p[11],'statLabel':p[12],'github':p[13],'live':p[14]} for p in projects]).replace("'",'"')};
const NEW_NOTES={repr([{'code':n[0],'title':n[1],'category':n[2],'desc':n[3],'insight':n[4],'color':n[5],'second':n[6],'points':n[7],'related':n[8]} for n in notes]).replace("'",'"')};
window.previewActiveIndex=0;
function previewOrb(c1,c2){{return `<div class="universe-fallback" style="--scene-primary:${{c1}};--scene-secondary:${{c2}}"><div class="universe-fallback__orbit orbit-one"></div><div class="universe-fallback__orbit orbit-two"></div><div class="universe-fallback__solid"></div><div class="universe-fallback__small one"></div><div class="universe-fallback__small two"></div></div>`}}
function previewSelect(raw){{const i=(raw+NEW_PROJECTS.length)%NEW_PROJECTS.length;window.previewActiveIndex=i;let p=NEW_PROJECTS[i];window.previewActiveId=p.id;let s=document.getElementById('preview-stage');s.style.setProperty('--stage-accent',p.accent);s.style.setProperty('--stage-secondary',p.secondary);s.style.setProperty('--stage-glow',p.glow);s.style.setProperty('--stage-surface',p.surface);document.getElementById('stage-label').innerText='NOW VIEWING / '+p.label;document.getElementById('stage-number').innerHTML=String(i+1).padStart(2,'0')+' <span>/ 06</span>';document.getElementById('stage-title').innerHTML=p.title+'<span>.</span>';document.getElementById('stage-desc').innerText=p.desc;document.getElementById('stage-stack').innerHTML=p.stack.map(v=>'<span>'+v+'</span>').join('');document.getElementById('stage-orb').innerHTML=previewOrb(p.accent,p.secondary);document.getElementById('stage-stat').innerText=p.stat;document.getElementById('stage-stat-label').innerText=p.statLabel;document.getElementById('stage-github').href=p.github;document.getElementById('stage-demo').style.display=p.live?'inline-flex':'none';document.getElementById('stage-demo').href=p.live||'#';document.getElementById('stage-steps').innerHTML=NEW_PROJECTS.map((e,index)=>`<button class="${{i===index?'active':''}}" onclick="previewSelect(${{index}})" aria-label="Show ${{e.title}}"><span></span>${{String(index+1).padStart(2,'0')}}</button>`).join('')}}
function previewFilter(cat,button){{document.querySelectorAll('.filter-pill').forEach(b=>b.classList.toggle('active',b===button));document.querySelectorAll('.universe-card').forEach(el=>{{el.style.display=cat==='All work'||el.dataset.category===cat?'':'none'}})}}
function previewLab(index){{let n=NEW_NOTES[index];document.querySelectorAll('.lab-index__item').forEach((el,i)=>el.classList.toggle('active',i===index));let el=document.getElementById('lab-preview-display');el.style.setProperty('--lab-color',n.color);el.style.setProperty('--lab-color-two',n.second);document.getElementById('lab-code').innerText='EXPERIMENT / '+n.code;document.getElementById('lab-cat').innerText='TECHNICAL EXPLORATION / '+n.category;document.getElementById('lab-title').innerText=n.title;document.getElementById('lab-desc').innerText=n.desc;document.getElementById('lab-insight').innerText=n.insight;document.getElementById('lab-points').innerHTML=n.points.map(t=>'<li>'+t+'</li>').join('');document.getElementById('lab-index').innerText='INSIGHT RECORD / '+String(index+1).padStart(2,'0')+' OF 03';document.getElementById('lab-related').onclick=()=>previewSelect(n.related==='tesla'?1:0)}}
function previewOpen(id){{let p=NEW_PROJECTS.find(x=>x.id===id);document.getElementById('dialog-project-title').innerText=p.title;document.getElementById('dialog-project-text').innerText=p.desc;document.getElementById('dialog-project-link').href=p.github;document.getElementById('preview-dialog').classList.add('open')}}
function previewClose(){{document.getElementById('preview-dialog').classList.remove('open')}}
previewSelect(0);previewLab(0);
'''
preview_dialog='''<div class="preview-dialog-cover" id="preview-dialog" role="presentation" onclick="if(event.target===this)previewClose()"><div class="preview-dialog-card" role="dialog" aria-label="Project details"><button class="preview-dialog-close" onclick="previewClose()" aria-label="Close">×</button><div class="lab-display__caption">PROJECT CASE STUDY / PREVIEW</div><h2 id="dialog-project-title"></h2><p id="dialog-project-text"></p><a target="_blank" id="dialog-project-link">VIEW SOURCE ↗</a></div></div>'''
base=base.replace('</script></body></html>',script+'</script>'+preview_dialog+'</body></html>')
(ROOT/'offline-preview.html').write_text(base)
